def points_inside_hull(test_points: np.ndarray, hull: ConvexHull, tol: float = 1e-10) -> np.ndarray:
    """Return boolean mask of test_points that lie inside (or on) the convex hull.

    Uses the half-space representation: a point is inside if it satisfies
    all facet inequalities  A @ x + b <= 0  (with a small tolerance).
    """
    # hull.equations shape: (n_facets, 4)  →  [a, b, c, d] per facet
    # For each test point we evaluate: A[:, :3] @ p + A[:, 3] <= tol
    A = hull.equations[:, :3]   # (n_facets, 3)
    b = hull.equations[:, 3]    # (n_facets,)
    # result shape: (n_facets, n_test_points)
    inside = (A @ test_points.T + b[:, np.newaxis]) <= tol
    return np.all(inside, axis=0)  # (n_test_points,)


# Group points by order.
order_groups = {order: grp[['x', 'y', 'z']].values
                for order, grp in points_df.groupby('order')}

orders = sorted(order_groups.keys())

# Build convex hulls; skip orders with fewer than 4 non-coplanar points.
hulls = {}
skipped = []
for order, pts in order_groups.items():
    if len(pts) < 4:
        skipped.append(f"{order} (n={len(pts)}, too few points)")
        continue
    try:
        hulls[order] = ConvexHull(pts)
    except Exception as e:
        skipped.append(f"{order}: {e}")

if skipped:
    print("Skipped orders (no hull computed):")
    for s in skipped:
        print(" •", s)

print(f"\nConvex hulls built for {len(hulls)} orders.")

# For each order with a hull, count how many points from *other* orders fall inside.
# Results stored as a dict-of-dicts: results[hull_order][intruding_order] = count
results = {}
for hull_order, hull in hulls.items():
    results[hull_order] = {}
    for other_order, other_pts in order_groups.items():
        if other_order == hull_order:
            continue
        mask = points_inside_hull(other_pts, hull)
        count = int(mask.sum())
        if count > 0:
            results[hull_order][other_order] = count

